/* prog43_catalan.c
 * Re‑implementation of the original obfuscated binary.
 * Behaviour:
 *   - No argument      → prints "NO_INPUT"
 *   - Invalid integer → prints "BAD_INPUT"
 *   - n < 1 or n > 30 → prints "OUT_OF_RANGE"
 *   - otherwise       → prints Catalan(n‑1) as a signed 64‑bit integer.
 *
 * The program uses only the C standard library.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

/* Compute Catalan numbers up to C[30] using 64‑bit arithmetic.
   The values are pre‑computed at program start for simplicity. */
static void fill_catalan(long long cat[31])
{
    cat[0] = 1;                     /* C0 */
    for (int n = 1; n <= 30; ++n) {
        long long sum = 0;
        for (int i = 0; i < n; ++i) {
            sum += cat[i] * cat[n - 1 - i];
        }
        cat[n] = sum;               /* Cn */
    }
}

/* Try to parse a decimal integer from a string.
   Returns 0 on success, non‑zero on failure.
   The parsed value is stored in *out. */
static int parse_int(const char *s, long long *out)
{
    char *endptr;
    errno = 0;
    long long val = strtoll(s, &endptr, 10);

    /* No digits at all? */
    if (endptr == s)
        return -1;

    /* Trailing characters? (the original program treats this as BAD_INPUT) */
    if (*endptr != '\0')
        return -1;

    /* Overflow / underflow? */
    if (errno == ERANGE)
        return -1;

    *out = val;
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    long long n;
    if (parse_int(argv[1], &n) != 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 1 || n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long catalan[31];
    fill_catalan(catalan);

    /* The original program prints C_{n-1}. */
    printf("%lld\n", catalan[n - 1]);
    return 0;
}
